// Extract page ID from Notion URL
const body = $input.item.json.body;
const url = body.url;

if (!url) {
  return { json: { error: 'No URL provided' } };
}

// Extract page ID from various Notion URL formats
let pageId;
const patterns = [
  /notion\.so\/([a-zA-Z0-9]+)(?:\?|#|$)/,
  /notion\.so\/.*-([a-f0-9]{32})(?:\?|#|$)/,
];

for (const pattern of patterns) {
  const match = url.match(pattern);
  if (match) {
    pageId = match[1];
    break;
  }
}

if (!pageId) {
  return { json: { error: 'Could not extract page ID from URL', url } };
}

return { json: { pageId, originalUrl: url } };

// Process blocks and create URLs
const pageId = $('Extract Page ID').item.json.pageId;
const blocks = $input.all();

const blockData = blocks.map(block => {
  const blockJson = block.json;
  const blockId = blockJson.id.replace(/-/g, ''); // Remove hyphens
  const blockUrl = `https://www.notion.so/${pageId}#${blockId}`;

  return {
    blockId: blockJson.id,
    blockUrl,
    type: blockJson.type,
    // Extract text content based on block type
    content: extractContent(blockJson),
    hasChildren: blockJson.has_children
  };
});

function extractContent(block) {
  const type = block.type;

  // Handle different block types
  if (block[type]?.rich_text) {
    return block[type].rich_text
      .map(rt => rt.plain_text)
      .join('');
  }

  // For other types, return a description
  switch(type) {
    case 'table':
      return `Table with ${block[type]?.table_width || 0} columns`;
    case 'equation':
      return block[type]?.expression || 'Equation';
    case 'divider':
      return '---';
    case 'child_page':
      return block[type]?.title || 'Child page';
    default:
      return `${type} block`;
  }
}

return blockData.map(data => ({ json: data }));
